function pointOn(t,lateral=0){const p=trackCurve.getPointAt(((t%1)+1)%1),tan=trackCurve.getTangentAt(((t%1)+1)%1),side=new THREE.Vector3(tan.z,0,-tan.x).normalize();return {p:p.addScaledVector(side,lateral),tan,side};}
function makeCar(color,isPlayer=false){const root=new THREE.Group(),paint=new THREE.MeshPhysicalMaterial({color,roughness:.27,metalness:.2,clearcoat:.85,clearcoatRoughness:.2}),dark=mat(0x151b1b,.5),rubber=mat(0x101212,.85),glass=new THREE.MeshPhysicalMaterial({color:0x172b30,roughness:.12,metalness:.25,clearcoat:1}),accent=new THREE.MeshStandardMaterial({color:isPlayer?0xd8ff3e:0xf0f0e5,emissive:isPlayer?0x526e00:0x000000,roughness:.4});
// Formula silhouette: nose points along +Z
addBox(root,'chassis',[0,.48,0],[1.7,.42,3.8],paint);const nose=new THREE.Mesh(new THREE.ConeGeometry(.68,2.4,4),paint);nose.rotation.x=Math.PI/2;nose.position.set(0,.42,2.65);root.add(nose);addBox(root,'front-wing',[0,.36,3.3],[3.1,.15,.57],dark);addBox(root,'wing-flap',[0,.52,3.38],[2.65,.12,.28],accent);addBox(root,'rear-wing',[0,.9,-1.62],[2.55,.18,.42],paint);addBox(root,'rear-wing-support',[0,.72,-1.48],[.2,.48,.2],dark);
const cockpit=new THREE.Mesh(new THREE.SphereGeometry(.65,16,12),glass);cockpit.scale.set(.74,.52,1.05);cockpit.position.set(0,.86,.05);root.add(cockpit);addBox(root,'halo',[0,1.15,.11],[1.1,.09,.08],dark);
for(const x of [-1,1])for(const z of [-1.25,1.28]){const tire=new THREE.Mesh(new THREE.CylinderGeometry(.39,.39,.32,16),rubber);tire.rotation.z=Math.PI/2;tire.position.set(x*.96,.39,z);tire.castShadow=true;root.add(tire);const hub=new THREE.Mesh(new THREE.CylinderGeometry(.19,.19,.34,12),mat(0xaab3ad,.3,.7));hub.rotation.z=Math.PI/2;hub.position.copy(tire.position);root.add(hub)}
// sidepods and nose stripes
for(const x of [-.9,.9])addBox(root,'sidepod',[x,.47,-.05],[.3,.34,1.55],paint);addBox(root,'nose-stripe',[0,.7,1.05],[.09,.035,1.7],accent);
if(isPlayer){for(const x of [-.6,.6]){const light=new THREE.PointLight(0xd8ff3e,1.2,5);light.position.set(x,.65,-1.7);root.add(light)}}root.traverse(o=>{if(o.isMesh){o.castShadow=true;o.receiveShadow=true}});scene.add(root);return root;}
function createCars(){player={mesh:makeCar(colors[0],true),progress:0,lateral:0,speed:30,targetSpeed:39,isPlayer:true,finished:false};racers=[player];for(let i=1;i<8;i++){const mesh=makeCar(colors[i]);const progress=-.025*(i%3)-.012*Math.floor(i/3),lateral=((i%3)-1)*2.65;racers.push({mesh,progress,lateral,speed:30+Math.random()*5,targetSpeed:31.5+Math.random()*6,phase:Math.random()*10,isPlayer:false,name:['NOVA','KITE','VEX','MIRA','SOL','ACE','JUNO'][i-1],finished:false})}
for(let i=0;i<racers.length;i++)updateCarTransform(racers[i],0);const initial=pointOn(.01,0);camera.position.set(initial.p.x-10,9,initial.p.z-18);camera.lookAt(initial.p.x,0,initial.p.z+8);}
function updateCarTransform(r,dt){const q=pointOn(r.progress,r.lateral),pos=q.p;pos.y+=.46;if(r.isPlayer){const turn=steer; r.mesh.rotation.y=Math.atan2(q.tan.x,q.tan.z)-turn*.055;r.mesh.rotation.z=THREE.MathUtils.damp(r.mesh.rotation.z,-turn*.075,5,dt)}else r.mesh.rotation.y=Math.atan2(q.tan.x,q.tan.z);r.mesh.position.copy(pos);}
function resize(){if(!renderer)return;renderer.setSize(innerWidth,innerHeight);camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();}
function bindControls(){const keyMap={ArrowLeft:-1,KeyA:-1,ArrowRight:1,KeyD:1};window.addEventListener('keydown',e=>{if(keyMap[e.code]){steerTarget=keyMap[e.code];e.preventDefault()}if(e.code==='Escape'||e.code==='KeyP'){togglePause()}if(e.code==='Space'&&running&&!paused){e.preventDefault()}});window.addEventListener('keyup',e=>{if(keyMap[e.code]){const other=keyMap[e.code]===1?-1:1;if(keyMap[e.code]===steerTarget)steerTarget=0;}});
const bind=(id,val)=>{const el=$(id);el.addEventListener('pointerdown',e=>{e.preventDefault();steerTarget=val;el.classList.add('down');el.setPointerCapture(e.pointerId)});const up=e=>{steerTarget=0;el.classList.remove('down')};el.addEventListener('pointerup',up);el.addEventListener('pointercancel',up);el.addEventListener('lostpointercapture',up)};bind('left',-1);bind('right',1);
let touchX=null;canvas.addEventListener('pointerdown',e=>{if(e.pointerType==='touch'){touchX=e.clientX}});canvas.addEventListener('pointermove',e=>{if(e.pointerType==='touch'&&touchX!==null){const dx=e.clientX-touchX;if(Math.abs(dx)>12)steerTarget=dx>0?1:-1;touchX=e.clientX}});canvas.addEventListener('pointerup',()=>{touchX=null;steerTarget=0});
$('start').onclick=startRace;$('restart').onclick=()=>{resetRace();startRace()};$('pause').onclick=togglePause;$('resume').onclick=togglePause;}
function resetRace(){racers.forEach((r,i)=>{r.progress=i===0?0:-.025*(i%3)-.012*Math.floor(i/3);r.lateral=i===0?0:((i%3)-1)*2.65;r.speed=30;r.finished=false;r.mesh.visible=true;updateCarTransform(r,0)});elapsed=0;lap=0;prevProgress=0;gateCount=0;bestLap=Infinity;lapStarted=0;activePower=null;powerTime=0;lastGate=-1;finished=false;gates.forEach(g=>{g.used=false;g.group.visible=true});$('powerName').textContent='READY FOR PICKUP';$('powertimer').style.width='0%';$('hud').classList.remove('show');$('finish').classList.add('hidden')}
function startRace(){resetRace();$('intro').classList.add('hidden');$('hud').classList.add('show');$('pause').classList.add('show');running=true;paused=false;raceStart=performance.now();lapStarted=0;clock.getDelta();}
function togglePause(){if(!running||finished)return;paused=!paused;$('pauseOverlay').classList.toggle('on',paused);$('pause').textContent=paused?'▶  RESUME':'Ⅱ  PAUSE';if(!paused)clock.getDelta();}

